# Inject before Render-CurrentCharacter.
marker='function Render-CurrentCharacter'
if marker not in core: raise SystemExit('Render-CurrentCharacter marker missing')
core=core.replace(marker,func+'\n'+marker,1)
# Route Timeline to custom renderer before Powers custom renderer or generic field rendering.
needle="if($script:ActiveSection -eq 'Powers')"
if needle not in core:
    # emit nearby clues for workflow log
    hits=[line for line in core.splitlines() if 'ActiveSection' in line and ('Powers' in line or 'Story' in line or 'Timeline' in line)]
    raise SystemExit('Powers renderer hook missing; clues='+repr(hits[:20]))
