files['TheFilesCore.ps1']['contentBase64']=base64.b64encode(new_core).decode();files['TheFilesCore.ps1']['sha256']=hashlib.sha256(new_core).hexdigest()
files['TheFilesCore.ps1.gz']['contentBase64']=base64.b64encode(new_gz).decode();files['TheFilesCore.ps1.gz']['sha256']=hashlib.sha256(new_gz).hexdigest()
